/** Every tutorial quiz joins the bank as single-choice questions. */
export function examBank(): ExamQ[] {
  const fromTutorials: ExamQ[] = TUTORIALS.flatMap(t => t.quiz.map((q, i) => ({
    id: `t-${t.id}-${i}`, area: t.area, skill: t.title, type: 'single' as const, stem: q.q, options: q.options, answer: q.answer, why: q.why, lab: t.id,
  })));
  return [...BANK, ...fromTutorials];
}

/** True when the response is fully correct. */
export function isCorrect(q: ExamQ, r: unknown): boolean {
  if (r === undefined || r === null) return false;
  switch (q.type) {
    case 'single': return r === q.answer;
    case 'multi': { const a = [...(q.answer as number[])].sort(), b = [...(r as number[])].sort(); return a.length === b.length && a.every((x, i) => x === b[i]); }
    case 'yesno': case 'order': { const a = q.answer as number[], b = r as number[]; return a.length === b.length && a.every((x, i) => x === b[i]); }
    case 'dropdown': { const b = r as number[]; return q.blanks!.every((bl, i) => b[i] === bl.answer); }
  }
}

/** Partial-credit fraction used for scoring Yes/No and drop-down questions, as the real exam does per item. */
export function credit(q: ExamQ, r: unknown): number {
  if (r === undefined || r === null) return 0;
  if (q.type === 'yesno') { const a = q.answer as number[], b = r as number[]; return a.filter((x, i) => b[i] === x).length / a.length; }
  if (q.type === 'dropdown') { const b = r as number[]; return q.blanks!.filter((bl, i) => b[i] === bl.answer).length / q.blanks!.length; }
  return isCorrect(q, r) ? 1 : 0;
}

